import React from 'react'

export const dash = {
  strokeDasharray: 520,
  strokeDashoffset: 520,
}

function StrokePath({ d, className = '', strokeWidth = 3, style }) {
  return (
    <path
      d={d}
      fill="none"
      stroke="currentColor"
      strokeWidth={strokeWidth}
      strokeLinecap="round"
      strokeLinejoin="round"
      vectorEffect="non-scaling-stroke"
      className={className}
      style={style}
    />
  )
}

const OutfitIconSingleLoader = ({ className = '' }) => {
  return (
    <div className={`flex flex-col items-center gap-3 ${className}`}>
      <div className="w-[160px] h-[160px] rounded-2xl bg-card shadow-sm flex items-center justify-center">
        <svg
          width="110"
          height="110"
          viewBox="0 0 100 100"
          className="text-foreground animate-float"
          aria-hidden="true"
        >
          {/* 1) 티셔츠 */}
          <g className="slot slot1">
            <TShirt drawClass="draw1" />
          </g>

          {/* 2) 바지 */}
          <g className="slot slot2">
            <Pants drawClass="draw2" />
          </g>

          {/* 3) 후디 */}
          <g className="slot slot3">
            <Hoodie drawClass="draw3" />
          </g>

          {/* 4) 원피스 (재제작) */}
          <g className="slot slot4">
            <Dress drawClass="draw4" />
          </g>

          {/* 5) 구두 (재제작) */}
          <g className="slot slot5">
            <Heels drawClass="draw5" />
          </g>
        </svg>
      </div>

      <p className="text-sm text-muted-foreground animate-fadePulse">
        코디 추천 생성중…
      </p>
    </div>
  )
}

